<?php foreach ($databaseSections as $section): ?><section class="surface" style="margin-top:1rem"><div class="surface-heading"><div><h2><?= rc_e($section['title']) ?></h2></div><span class="result-count"><?= count($section['rows']) ?> rows</span></div><?php if ($section['rows']): ?><div class="table-wrap"><table><thead><tr><?php foreach (array_keys($section['rows'][0]) as $column): ?><th><?= rc_e($column) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($section['rows'] as $row): ?><tr><?php foreach ($row as $value): ?><td><?= rc_e($value) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">No matching records in this database.</p><?php endif; ?></section><?php endforeach; ?>
<section class="surface" style="margin-top:1rem"><div class="surface-heading"><div><h2>Trigger applications</h2><span>Installed database protections and automatic actions</span></div><span class="result-count"><?= count($databaseTriggers) ?> triggers</span></div><div class="table-wrap"><table><thead><tr><th>Application</th><th>Trigger</th><th>Database behavior</th></tr></thead><tbody><tr><td>Validation</td><td><code>trg_order_items_quantity_insert/update</code></td><td>Rejects product order-line quantities below 1 with “Product quantity must be at least 1.”</td></tr><tr><td>Business rules</td><td><code>trg_orders_rules_insert/update</code></td><td>Requires a valid guest count and payment amounts; confirmation needs the deposit and completion needs full payment.</td></tr><tr><td>Auditing changes</td><td><code>trg_orders_audit_update</code></td><td>Stores before-and-after order status and payment values in <code>audit_logs</code>.</td></tr><tr><td>Automatic data logging</td><td><code>trg_payments_log_insert</code></td><td>Writes each inserted payment to <code>database_activity_log</code>.</td></tr></tbody></table></div><details style="padding:0 1.25rem 1rem"><summary>Installed trigger catalog</summary><?php if ($databaseTriggers): ?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Table</th><th>Timing</th><th>Event</th></tr></thead><tbody><?php foreach ($databaseTriggers as $trigger): ?><tr><td><?= rc_e($trigger['TRIGGER_NAME']) ?></td><td><?= rc_e($trigger['EVENT_OBJECT_TABLE']) ?></td><td><?= rc_e($trigger['ACTION_TIMING']) ?></td><td><?= rc_e($trigger['EVENT_MANIPULATION']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">No triggers are installed in this schema.</p><?php endif; ?></details></section>
<section class="surface" style="margin-top:1rem"><div class="surface-heading"><div><h2>Auditing changes</h2><span>Order before-and-after snapshots created by the audit trigger</span></div></div><?php if ($triggerAuditRows): ?><div class="table-wrap"><table><thead><tr><th>When</th><th>Entity</th><th>Record</th><th>Before</th><th>After</th></tr></thead><tbody><?php foreach ($triggerAuditRows as $row): ?><tr><td><?= rc_e($row['created_at']) ?></td><td><?= rc_e($row['entity_type']) ?></td><td><?= rc_e($row['entity_id']) ?></td><td class="audit-value"><?= rc_e($row['old_value']) ?></td><td class="audit-value"><?= rc_e($row['new_value']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">No order changes have been captured by the database audit trigger yet.</p><?php endif; ?></section>
<section class="surface" style="margin-top:1rem"><div class="surface-heading"><div><h2>Automatic data log</h2><span>Payment inserts recorded by a database trigger</span></div></div><?php if ($activityRows): ?><div class="table-wrap"><table><thead><tr><th>When</th><th>Table</th><th>Record</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach ($activityRows as $row): ?><tr><td><?= rc_e($row['logged_at']) ?></td><td><?= rc_e($row['table_name']) ?></td><td><?= rc_e($row['record_id']) ?></td><td><?= rc_e($row['action_name']) ?></td><td><?= rc_e($row['details']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">No payment insert events have been logged yet.</p><?php endif; ?></section>
